/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import FluidPressureAndFlowColors from "../../src/FluidPressureAndFlowColors.js";
import { FlowScreen } from "../../src/flow/FlowScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { FluidPressureAndFlowPreferencesModel } from "../../src/preferences/FluidPressureAndFlowPreferencesModel.js";
import { UnderPressureScreen } from "../../src/under-pressure/UnderPressureScreen.js";
import { WaterTowerScreen } from "../../src/water-tower/WaterTowerScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from fluidPressureAndFlowQueryParameters.
  const simPreferences = new FluidPressureAndFlowPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  // One unit system shared by all three screens, gated on the "match units"
  // preference. Built here because no single screen owns it.
  const sharedUnits = {
    sharedUnitSystemProperty: simPreferences.sharedUnitSystemProperty,
    linkUnitsProperty: simPreferences.linkUnitsProperty,
  };

  const screens = [
    new UnderPressureScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().underPressureStringProperty,
      tandem: Tandem.ROOT.createTandem("underPressureScreen"),
      backgroundColorProperty: FluidPressureAndFlowColors.backgroundColorProperty,
      sharedUnits: sharedUnits,
    }),
    new FlowScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().flowStringProperty,
      tandem: Tandem.ROOT.createTandem("flowScreen"),
      backgroundColorProperty: FluidPressureAndFlowColors.backgroundColorProperty,
      sharedUnits: sharedUnits,
    }),
    new WaterTowerScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().waterTowerStringProperty,
      tandem: Tandem.ROOT.createTandem("waterTowerScreen"),
      backgroundColorProperty: FluidPressureAndFlowColors.backgroundColorProperty,
      sharedUnits: sharedUnits,
    }),
  ];

  return { screens, tracked: { FluidPressureAndFlowColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
